//! Help › About: what the program is, its licence and where it lives, and the third-party
//! notices of everything it is built from. The engine knows the licence and the addresses; the
//! front end names itself, its version and build, and gives the notices its build embedded
//! (generated by `xtask/src/notices.rs`).

use serde::{de::Error as _, Deserialize};

use crate::{
    commands::{ids, register, spec},
    CommandCategory, CommandContext, CommandOutcome, CommandRegistry,
};

/// Where the documentation is published.
pub const DOCUMENTATION: &str = "https://bovinemagnet.github.io/AdocFoundry";

/// What Help › About shows.
#[derive(Clone, Debug, PartialEq)]
pub struct About {
    pub name: String,
    pub version: String,
    /// The target and profile the program was built for, when the front end knows them.
    pub build: Option<String>,
    /// The program's licence, as an SPDX expression, and its text (`LICENSE`).
    pub licence: &'static str,
    pub licence_text: &'static str,
    pub repository: &'static str,
    pub documentation: &'static str,
    pub notices: Notices,
}

impl Default for About {
    fn default() -> Self {
        Self {
            name: "AdocFoundry".to_owned(),
            version: env!("CARGO_PKG_VERSION").to_owned(),
            build: None,
            licence: env!("CARGO_PKG_LICENSE"),
            licence_text: include_str!("../../../LICENSE"),
            repository: env!("CARGO_PKG_REPOSITORY"),
            documentation: DOCUMENTATION,
            notices: Notices::default(),
        }
    }
}

impl About {
    /// Names the program the front end is, with its version and build.
    #[must_use]
    pub fn program(mut self, name: &str, version: &str, build: Option<&str>) -> Self {
        self.name = name.to_owned();
        self.version = version.to_owned();
        self.build = build.map(str::to_owned);
        self
    }

    #[must_use]
    pub fn notices(mut self, notices: Notices) -> Self {
        self.notices = notices;
        self
    }
}

/// The third-party components a program is built from, sorted by name, and the licence texts
/// they share.
#[derive(Clone, Debug, Default, PartialEq, Deserialize)]
pub struct Notices {
    pub components: Vec<Notice>,
    texts: Vec<String>,
}

/// One component: a crate, or a bundled font, dictionary or theme.
#[derive(Clone, Debug, PartialEq, Deserialize)]
pub struct Notice {
    pub name: String,
    pub version: String,
    pub licence: String,
    /// Why the text is its licence's standard text, when it ships no licence file.
    pub note: Option<String>,
    /// Each licence file's name and its text, an index into `Notices::texts`.
    texts: Vec<(String, usize)>,
}

impl Notices {
    /// Reads the notices a build embedded, refusing any that names a text they lack.
    pub fn from_json(json: &str) -> Result<Self, serde_json::Error> {
        let notices: Self = serde_json::from_str(json)?;
        let count = notices.texts.len();
        if let Some(notice) = notices
            .components
            .iter()
            .find(|notice| notice.texts.iter().any(|(_, index)| *index >= count))
        {
            return Err(serde_json::Error::custom(format!(
                "{} names a licence text the notices lack",
                notice.name
            )));
        }
        Ok(notices)
    }

    /// `notice`'s licence texts, each with the name of its file.
    pub fn texts<'a>(&'a self, notice: &'a Notice) -> impl Iterator<Item = (&'a str, &'a str)> {
        notice
            .texts
            .iter()
            .map(|(file, index)| (file.as_str(), self.texts[*index].as_str()))
    }

    /// `notice` as one text, to read or copy: its name and licence, its note, then each text
    /// under its file's name.
    pub fn text(&self, notice: &Notice) -> String {
        let mut text = format!(
            "{} {}\nLicence: {}\n",
            notice.name, notice.version, notice.licence
        );
        if let Some(note) = &notice.note {
            text.push_str(&format!("\n{note}\n"));
        }
        for (file, body) in self.texts(notice) {
            text.push_str(&format!("\n{file}\n\n{body}\n"));
        }
        text
    }
}

pub(crate) fn register_about(registry: &mut CommandRegistry) {
    register(
        registry,
        spec(
            ids::APP_ABOUT,
            "About AdocFoundry",
            CommandCategory::Help,
            None,
            CommandContext::Always,
        ),
        |_, _| Ok(CommandOutcome::About(Box::default())),
    );
}
